import pickle, json, io

data = {"name": "Ana", "scores": [10, 9, 8]}

buffer = io.BytesIO()
pickle.dump(data, buffer)
buffer.seek(0)
restored = pickle.load(buffer)
print(restored == data)

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

def point_to_dict(obj):
    if isinstance(obj, Point):
        return {"x": obj.x, "y": obj.y}
    raise TypeError

p = Point(3, 4)
print(json.dumps(p, default=point_to_dict, sort_keys=True))
